/**
 * Retrieves the translation of text.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-i18n/
 */
import { __ } from '@wordpress/i18n';

/**
 * React hook that is used to mark the block wrapper element.
 * It provides all the necessary props like the class name.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-block-editor/#useblockprops
 */
import { useBlockProps, RichText, MediaUpload, InspectorControls } from '@wordpress/block-editor';
import { PanelBody, PanelRow, TextControl, CheckboxControl, ToggleControl, Button } from '@wordpress/components';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * Those files can contain any CSS code that gets applied to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './editor.scss';

/**
 * The edit function describes the structure of your block in the context of the
 * editor. This represents what the editor will render when the block is used.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-edit-save/#edit
 *
 * @return {Element} Element to render.
 */
export default function Edit( { attributes, setAttributes } ) {

	const TagName = attributes.switch_option ? "a" : "div";
	const tagProps = attributes.switch_option
		? { href: attributes.list_id }
		: {};

	return (
		<>
		<InspectorControls>
			<PanelBody title="Image Box Settings" initialOpen={ true }>
				
				<PanelRow>
					<CheckboxControl
						label="Show Text Only"
						checked={ attributes.doubleoption }
						onChange={ () => setAttributes( { doubleoption : ! attributes.doubleoption } ) }
					/>
				</PanelRow>
				<PanelRow>
					<ToggleControl
						label="Cart Link"
						checked={ attributes.switch_option }
						onChange={ () => setAttributes( { switch_option : ! attributes.switch_option } ) }
					/>
				</PanelRow>
				{ attributes.switch_option ? <PanelRow>
					<TextControl
						label="Cart link url"
						value={ attributes.list_id }
						onChange={ ( list_id ) => setAttributes( { list_id } ) }
					/>
				</PanelRow> : null }
			</PanelBody>
			<PanelBody title="Cart Image" initialOpen={ false }> 
					<MediaUpload
						title={ __( 'Upload Cart Image', 'tblock' ) }
						allowedTypes={ [ 'image/jpeg', 'image/jpg', 'image/png' ] }
						value={ attributes.image.id }
						onSelect={ ( image ) => setAttributes( { image: { id: image.id, url: image.url } } ) }
						render={ ( { open } ) => {
							if ( 0 === attributes.image.id ) {
								return <Button onClick={ open }>{ __( 'Upload Image', 'tblock' ) }</Button>;
							} else {
								return <>
									<img src={ attributes.image.url } onClick={ open } />
									<Button onClick={ (image) => setAttributes( { image: { id: 0, url: '' } } ) }>
										{ __( 'Delete Image', 'tblock' ) }
									</Button>
								</>;
							}
						} }
					/>
			</PanelBody>
		</InspectorControls>
			<div { ...useBlockProps() }>
				<TagName className="tblock-card-wrap" { ...tagProps } >
					
						{ attributes.doubleoption ? null : <div className="tblock-img" style={{backgroundImage: `url( ${attributes.image.url} )` }}></div>	}
						<div className="tblock-content">
							<RichText
								tagName="strong"
								className="tblock-title"
								placeholder="Enter title text"
								value={ attributes.titletext }
								allowedFormats={[ "core/bold", "core/italic", "core/link" ]}
								onChange={ ( titletext ) => setAttributes( { titletext } ) }
							/>
							<RichText
								tagName="p"
								className="tblock-des"
								placeholder="Enter description text"
								value={ attributes.descriptiontext }
								allowedFormats={[ "core/bold", "core/italic", "core/link" ]}
								onChange={ ( descriptiontext ) => setAttributes( { descriptiontext } ) }
							/>
							
						</div>
						
				</TagName>
			</div>
		</>
	);
}
