/**
 * React hook that is used to mark the block wrapper element.
 * It provides all the necessary props like the class name.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-block-editor/#useblockprops
 */
import { useBlockProps, RichText  } from '@wordpress/block-editor';

/**
 * The save function defines the way in which the different attributes should
 * be combined into the final markup, which is then serialized by the block
 * editor into `post_content`.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-edit-save/#save
 *
 * @return {Element} Element to render.
 */
export default function save( { attributes } ) {

	let actionUrl = '';
	if ( attributes.list_id ) {
		actionUrl = 'https://gmail.us21.list-manage.com/subscribe/post?u=YOUR_U_VALUE&id=' + attributes.list_id;
	} else {
		actionUrl = '#';
	}

	const TagName = attributes.switch_option ? "a" : "div";
	const tagProps = attributes.switch_option
		? { href: attributes.list_id }
		: {};
	

	return (
		<div { ...useBlockProps.save() }>
			<TagName className="tblock-card-wrap" {...tagProps} >

				{ attributes.doubleoption ? null : <div className="tblock-img" style={{backgroundImage : `url(${attributes.image.url})` }}></div>  }
				<div className="tblock-content">
					<RichText.Content tagName="strong" className="tblock-title" value={ attributes.titletext } />
					<RichText.Content tagName="p" className="tblock-des" value={ attributes.descriptiontext } />
				</div>
				
			</TagName>
		</div>
	);
}
